const xExcludes = [_]struct { sym: u16, shift: u16 }{
};

fn getImmediateShift(_: u16, _: u16) ?i16 {
    return null;
}

fn startState(start: Start) u16 {
    return switch (start) {
        .@"program" => 0,
    };
}

fn startMarker(start: Start) u16 {
    return switch (start) {
        .@"program" => 160,
    };
}

