        .@"*" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"/" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"%" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"==" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"!=" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"<" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@">" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"<=" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@">=" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"&" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"|" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"^" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"<<" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@">>" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"??" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@".." => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"and" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"or" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"neg" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"not" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"move" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"read" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"write" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"clone" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"share" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"weak" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"optional" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"error_union" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"borrow_read" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"borrow_write" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"shared" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"slice" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"generic_inst" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"array_type" => switch (slot) {
            1 => .@"size",
            2 => .@"type",
            else => null,
        },
        .@"fun_type" => switch (slot) {
            1 => .@"params",
            2 => .@"returns",
            else => null,
        },
        else => null,
    };
}

fn restRoleOf(kind: Tag) ?struct { role: Role, slot: usize } {
    return switch (kind) {
        .@"module" => .{ .role = .@"decls", .slot = 1 },
        .@"struct" => .{ .role = .@"members", .slot = 2 },
        .@"enum" => .{ .role = .@"members", .slot = 2 },
        .@"errors" => .{ .role = .@"members", .slot = 2 },
        .@"generic_type" => .{ .role = .@"members", .slot = 3 },
        .@"generic_enum" => .{ .role = .@"members", .slot = 3 },
        .@"match" => .{ .role = .@"arms", .slot = 2 },
        .@"variant_pattern" => .{ .role = .@"bindings", .slot = 2 },
        .@"block" => .{ .role = .@"stmts", .slot = 1 },
        .@"captures" => .{ .role = .@"caps", .slot = 1 },
        .@"call" => .{ .role = .@"args", .slot = 2 },
        .@"builtin" => .{ .role = .@"args", .slot = 2 },
        .@"array" => .{ .role = .@"elems", .slot = 1 },
        .@"generic_inst" => .{ .role = .@"args", .slot = 2 },
        else => null,
    };
}

// =============================================================================
// API
// =============================================================================

pub const Parser = if (@hasDecl(lang, "Parser")) lang.Parser else BaseParser;

/// Parse a whole program with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseProgram(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
    errdefer p.deinit();
    const sexp = try p.parseProgram();
    return .{ .parser = p, .sexp = sexp };
}
